<?php
require_once 'config.php'; require_auth(); ensure_schema(); $pdo=db(); $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT wo.*,c.name client_name,c.phone,c.dni,v.brand,v.model,v.plate FROM work_orders wo JOIN clients c ON c.id=wo.client_id JOIN vehicles v ON v.id=wo.vehicle_id WHERE wo.id=?');$st->execute([$id]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Orden no encontrada');}$st=$pdo->prepare('SELECT * FROM budget_items WHERE order_id=? ORDER BY id');$st->execute([$id]);$items=$st->fetchAll();$st=$pdo->prepare('SELECT p.*,u.name user_name FROM payments p LEFT JOIN users u ON u.id=p.user_id WHERE order_id=? ORDER BY paid_at');$st->execute([$id]);$payments=$st->fetchAll();$t=order_totals($pdo,$id);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comprobante <?=h($o['code'])?></title><style>body{font-family:Arial,sans-serif;max-width:760px;margin:30px auto;color:#111;padding:20px}h1{margin:0}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:16px}.box{border:1px solid #ccc;padding:14px;margin-top:16px}.row{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #eee}.total{font-size:1.4rem;font-weight:bold}.muted{color:#666}@media print{body{margin:0;max-width:none}.no-print{display:none}}</style></head><body><div class="head"><div><h1><?=h(app_name())?></h1><div class="muted">Comprobante interno</div></div><div><strong><?=h($o['code'])?></strong><br><?=h(date_ar($o['created_at'],true))?></div></div><div class="box"><strong>Cliente:</strong> <?=h($o['client_name'])?><br><strong>Teléfono:</strong> <?=h($o['phone'])?><br><strong>Moto:</strong> <?=h($o['brand'].' '.$o['model'].' · '.$o['plate'])?></div><div class="box"><h3>Detalle</h3><?php foreach($items as $i):?><div class="row"><span><?=h($i['description'])?> × <?=h($i['quantity'])?></span><strong><?=h(money($i['quantity']*$i['unit_price']))?></strong></div><?php endforeach;?><div class="row total"><span>Total</span><span><?=h(money($t['total']))?></span></div><div class="row"><span>Pagado</span><span><?=h(money($t['paid']))?></span></div><div class="row total"><span>Saldo</span><span><?=h(money($t['balance']))?></span></div></div><div class="box"><h3>Pagos</h3><?php if($payments):foreach($payments as $p):?><div class="row"><span><?=h(date_ar($p['paid_at'],true).' · '.payment_method_label($p['method']))?></span><strong><?=h(money($p['amount']))?></strong></div><?php endforeach;else:?><span class="muted">Sin pagos registrados.</span><?php endif;?></div><button class="no-print" onclick="window.print()">Imprimir</button></body></html>
